INSERT INTO feature VALUES('ascription','calculus','Type ascription','call-by-push-value','implemented','ordinary',NULL,'A term ascribed a type synthesises it and checks the term against it: `(e : T)` ascribes the value it encloses wherever a value is read, an application''s head included, a computation is ascribed by `run d : T <- e`, which binds at a written type, a name or a tuple pattern alike, and the kernel replays each stated type where it synthesises.','core-term core-checker kernel-core surface-lowering','corpus/surface/typed-bind.gandr corpus/surface/typed-bind-parameters.gandr corpus/pathological/basics/ill-typed-ascription.gandr corpus/model/basics/annotations.gandr corpus/pathological/basics/annotations.gandr','corpus/surface/typed-bind.gandr',NULL,'#432 #1543');
INSERT INTO feature VALUES('atom-identity','identity','Identity at a sealed type','identity-by-recursion','partial','unique','dependent provers','A sealed type''s type member names its identity, @[ identity((relation, reflexivity, law)) ]: a reflexive relation whose singletons contract onto reflexivity is the type''s identity, so the relation''s evidence is a path at the atom and based path induction runs over it, computing along that evidence in a family reading neither entry, and in a family of identities at the atom, or of identities of them, whose relation returns the code of the unit type or of an identity of it outright, returning the unit; a relation returning the paths between its points is lawful by the same law; an interface naming no law refuses that evidence as AtomTransport.','surface-lowering core-checker core-nbe kernel-core','corpus/model/identity/atom-identity.gandr corpus/pathological/identity/atom-identity.gandr','corpus/model/identity/atom-identity.gandr','#2053','#1872 #1909 #1974 #2068');
INSERT INTO feature VALUES('atom-sorts','descriptions','Atom sorts','levitated-descriptions','partial','notable',NULL,'A theory block declares an atom sort, `sort Name : Atom;`, whose elements have equality and swapping as their only structure; the Theory value keeps it under its own tag, a binder over it is refused by name, and an operation''s port abstracts its atoms with `bind (a : Name) .` beside `pi+`, a model of such an operation refused by name. A rule term abstracts an atom at such a port, `bind a . t`, and matching, the critical pairs and the kernel read it up to the atom it names. Inside its abstraction a rule term names the atom, an occurrence counted by the abstractions between it and its binder, and an inspected call reads one alike. Where a port takes an atom, a rule stating a freshness condition or moving a variable across an abstraction fires only where its instance names no atom it may not, counting a moved instance''s atoms to their abstractions'' new places, and takes part in no critical pair: its overlap with another rule, and a variable split across an abstraction on a left side, are refused as undecided.','theory-levitation surface-lowering theory-computads kernel-term','corpus/model/desc/atom-sorts.gandr corpus/pathological/desc/atom-sorts.gandr corpus/model/desc/bind-port.gandr corpus/pathological/desc/bind-port.gandr corpus/model/desc/bind-term.gandr corpus/pathological/desc/bind-term.gandr corpus/model/desc/atom-occurrence.gandr corpus/pathological/desc/atom-occurrence.gandr','corpus/model/desc/atom-sorts.gandr','#1430 #1561 #1934','#1570 #1616 #1696 #1943 #1956');
