INSERT INTO feature VALUES('confluence-certificate','rules','Confluence as a certificate',NULL,'partial','notable',NULL,'The overlap enumeration as a convex pre-critical-pair criterion and the coincidence verdict as a replayable certificate; the diagram side enumerates the connected gluings of two left-hand sides, and on the corpus the term critical pairs are exactly the gluings at a redex (a command''s cut, any node of a term). A certificate is a path from a critical pair''s peak to its join in the presented type: two certificates of one boundary are one path by `here` where the rules relate their points, two that no rule relates stay apart, and the certificate types of two converting boundaries are one along `ua`.','theory-circuit-algebras','crates/surface-dispatcher/tests/coincide.rs corpus/model/desc/rules-overlap-joinable.gandr corpus/model/identity/certificate-transport.gandr corpus/pathological/identity/certificate-transport.gandr','corpus/model/desc/rules-overlap-joinable.gandr','#314 #525','#1495 #1849');
