INSERT INTO feature VALUES('dependent-transport','identity','Transport in path-dependent motives','transport','partial','notable',NULL,'A motive may depend on the identification itself, and path induction is derived in the singleton. Along a closed path that is no reflexivity, native evidence at the unit type or at a sealed atom, the transport computes in a motive reading neither entry; into an identity at a carrier whose identities are the unit type, the unit type itself, an identity of such a carrier, or a lawful atom whose relation returns the code of such a type outright, it returns the unit along any path.','core-nbe core-checker kernel-core','corpus/model/identity/transport-dependent.gandr corpus/model/identity/transport-dependent-element.gandr corpus/model/identity/atom-identity.gandr','corpus/model/identity/transport-dependent.gandr','#312 #2053','#266 #1909 #1957 #1974 #2068');
INSERT INTO feature VALUES('deprecation','attributes','Deprecated declarations','attributes','implemented','ordinary',NULL,'`@[ deprecated ]`, or `@[ deprecated(#{ since = "…", note = "…" }) ]` with either field left out, marks a declaration that still checks; each use of it is a `deprecated` warning naming the version and the note, struck through in the editor, the declaration''s symbol tagged and its hover stating both.','surface-lowering surface-diagnostics surface-dispatcher surface-lsp','corpus/model/attributes/doc-and-deprecated.gandr corpus/pathological/attributes/ill-typed-deprecation.gandr','corpus/model/attributes/doc-and-deprecated.gandr',NULL,'#1814');
