INSERT INTO feature VALUES('derived-rules','identity','Derived rules at a model (derive r : l <=> r in T)','univalence-theorem','partial','unique','dependent provers','`derive r : l <=> r in T` states an equation a theory''s completed rules prove, both sides rewritten to one normal form, and is proved for every model: a path over the model''s fields, each step the law or the lemma it fires carried up its context as `cong` is, each rule completion derived on the way proved first from its certificate''s two paths. A model reads it as the theory''s member `T.r`; sides the completion keeps apart are refused by name. A theory with an indexed sort or a nested model is not read yet.','surface-lowering surface-grammar','corpus/model/identity/derived-rule.gandr corpus/pathological/identity/derived-rule.gandr crates/surface-lowering/tests/modules/models.rs','corpus/model/identity/derived-rule.gandr','#1301','#1905');
INSERT INTO feature VALUES('descent-any-parameter','recursion','Descent on any parameter','structural-recursion','implemented','ordinary',NULL,'The lowering reads the staged position off the body: the parameter the claims'' cases take apart is the fixpoint''s first binder with StructuralDescent, the parameters before it outside and uniform, the ones after it free under the staged lambda; claims on two parameters refused DescentOnSeveralParameters; an unapplied f[<] is the self binder; a parameter before the recursed-on one may vary between calls. A constructor written as a descent''s argument takes its type from the parameter it fills, as an ordinary call''s does, a uniform parameter that type names standing for itself.','surface-lowering','corpus/model/data/descent.gandr corpus/pathological/data/descent.gandr corpus/model/identity/int-accumulated.gandr crates/surface-lowering/src/lower/native/tests.rs::a_descent_call_s_constructor_argument_takes_its_parameter_s_type_2127','corpus/model/data/descent.gandr','#392 #518','#629 #999');
