INSERT INTO feature VALUES('directed-paths','directed','Directed paths (Flow)',NULL,'partial','uncommon','mainstream languages','`Flow(A, a, b)` is a directed identification with `stay`, `then` and covariant transport `ride`, certified on readmission; `forward(f)` decides a closed translator at its finitely many patterns, a list code read as the empty list and one cell over a rigid tail, whose image may also bind the translator''s own image of the tail, replayed as the translator at the tail bound before the cell''s return; a data code with no index and no presentation, every field a closed type of the vocabulary, is read constructor by constructor, each applied to its fields'' patterns. A ⇝ B (A ~~> B) abbreviates Flow(Type, A, B) at the type level (#571).','core-checker kernel-core kernel-term','corpus/model/identity/flow-then.gandr corpus/pathological/identity/flow-forward-unsupported.gandr corpus/model/identity/flow-universe.gandr corpus/pathological/identity/flow-universe.gandr corpus/model/identity/flow-list-field.gandr corpus/model/identity/flow-list-each.gandr corpus/model/identity/flow-large.gandr corpus/model/identity/flow-data.gandr corpus/pathological/identity/flow-data.gandr','corpus/model/identity/flow-then.gandr','#1835','#296 #1769 #1771 #1838 #1842 #1927');
