INSERT INTO feature VALUES('divergence-row','effects','Divergence as a row entry','effect-rows','partial','uncommon','mainstream languages','A partial fixpoint checks only where every returner its type ends in holds `Div`, the host interface with no operation, which no handler or scope eliminates, so the empty row is the row of a computation that returns; a fixpoint that never names itself and a ruled operation''s need no entry. In a reflexivity''s endpoints, an unread call of a variable whose type ends in the empty row alone is the computation that follows it; the kernel refuses a partial fixpoint at a returner other than a ruled operation''s and replays the drop.','core-term core-checker core-nbe kernel-core kernel-term kernel-conversion-trace','corpus/model/control/divergence.gandr corpus/pathological/control/divergence.gandr','corpus/model/control/divergence.gandr','#1481','#1526 #1542');
