INSERT INTO feature VALUES('effect-handlers','effects','Effect handlers','effect-rows','implemented','uncommon','mainstream languages','A handler interprets the operations of a computation, each clause receiving the continuation; a handle is a reset whose clauses receive the captured stack, and a return leaving a handler prints as written with its capability''s region. A clause whose continuation captured an obligation ends it exactly once, by resuming it or by `abandon(k)`, and an abandonment is refused inside an unwind.','core-checker core-sequent surface-pretty','corpus/model/control/handler-exits.gandr corpus/model/control/capability-region.gandr corpus/pathological/control/capability-escape.gandr corpus/model/cancellation/abandoned.gandr corpus/pathological/cancellation/dropped.gandr corpus/pathological/cancellation/shielded.gandr corpus/model/drop/in-flight.gandr','corpus/model/control/handler-exits.gandr',NULL,'#98 #1299 #1376 #1415');
