INSERT INTO feature VALUES('equivalence-record','identity','Equivalences as a record type','univalence-theorem','partial','notable',NULL,'A ≃ B (A <~> B) is the bi-invertible record #{to, linv : #{g, sect}, rinv : #{h, retr}} and A ≅ B (Iso(A, B)) the quasi-inverse #{to, back, sect, retr}, both type formers lowered to the record they abbreviate with no kernel node, the printer and hover answering the former; isoToEquiv and equivToIso are corpus defs; the circle states winding : Path(Circle, Base, Base) ≃ Int. ua computing its certificate from the record is owed (#312).','surface-lowering','corpus/model/identity/equivalence.gandr corpus/model/identity/circle.gandr corpus/pathological/identity/iso-endpoint.gandr corpus/pathological/identity/equiv-fibres.gandr','corpus/model/identity/equivalence.gandr','#312','#571');
INSERT INTO feature VALUES('equivalences','identity','Equivalences decided by computation (equiv)',NULL,'implemented','notable',NULL,'`equiv(f, g)` certifies two maps mutually inverse by computation, between codes built from units, base atoms, sums, products, lists and data types that do not hold themselves, a data type read constructor by constructor, and a value moves along the equivalence. A function moves along it by its maps, its argument back and its result forward, in the normalizer and the kernel alike, so a structure with operations relates along its carrier''s equivalence, between one type or two.','core-checker core-nbe kernel-core surface-diagnostics','corpus/model/identity/transport-list.gandr corpus/pathological/identity/equiv-list-tail.gandr corpus/model/identity/structure-operations.gandr corpus/model/identity/equiv-data.gandr corpus/pathological/identity/equiv-data.gandr','corpus/model/identity/transport-list.gandr',NULL,'#259 #1075 #1099 #1344 #1760 #1958');
