INSERT INTO feature VALUES('first-class-stacks','effects','First-class continuations (Stack)','effect-handlers','implemented','uncommon','mainstream languages','A continuation has the type `Stack(C, D)`, the computation it resumes from and the one it ends as; one that captured an obligation is one-shot, resumed or abandoned exactly once, never dropped and never captured by a thunk. An abandoned stack runs the unwind of each access it captured, innermost first, and never its other frames.; a function stating `Stack(C, D)` resumes the continuation it is handed, as the clause that bound it would','core-term core-checker core-sequent runtime-emitter','corpus/model/control/handler-exits.gandr corpus/model/cancellation/resumed.gandr corpus/pathological/cancellation/leaked.gandr corpus/model/drop/unwritten.gandr corpus/model/drop/unwound.gandr corpus/model/self-reference/suspended.gandr corpus/model/self-reference/relocated.gandr corpus/pathological/cancellation/handed.gandr','corpus/model/control/handler-exits.gandr',NULL,'#98 #1376 #1415 #1438 #1671');
