INSERT INTO feature VALUES('formatter','printing','The source formatter',NULL,'implemented','ordinary',NULL,'`gandr fmt` lays a source out at a page width, keeping every token and comment and checking its meaning unchanged; each comment attached to the node it describes; `--form` and `@[ form(...) ]` rewrite between the sugared and the explicit spellings through a named rewrite table under the meaning check, a rewrite withdrawn visibly when it would change the meaning; the sugared form leaves a thunk type''s default grade `[ω]` and a tail return unwritten and writes a value-function alias at its shortest and a block''s linear runs at their reads, a match branch''s among them, a block left with no statement written as its one computation, checker-backed: a run is written away only where both spellings elaborate alike; a signature at a suspended returner or function and the thunk defining it are written as one function form in either form, each binder of the lambda the thunk holds a parameter at its domain; the whole corpus is held to the sugared form.','surface-format surface-dispatcher','crates/surface-format/tests/format.rs crates/surface-format/tests/rewrite.rs',NULL,NULL,'#158 #783 #793 #807 #828 #1339 #1349 #1373 #1423 #1532 #1914 #1972 #1975');
