INSERT INTO feature VALUES('generative-functors','modules','Generative functors','modules','implemented','notable',NULL,'A module parameterised by modules, each application minting fresh abstract types; a parameter is signed by a record signature or by Model(T), its components the ones the theory derives, each law stated at the parameter''s own operations; an argument names a module its source declares or one an unqualified import brings.','surface-lowering','corpus/model/modules/functor-pair.gandr corpus/pathological/modules/generative-distinctness.gandr corpus/model/modules/model-functor.gandr corpus/model/modules/model-functor-imported.gandr corpus/pathological/modules/functor-unexported.gandr corpus/pathological/modules/functor-mistyped.gandr','corpus/model/modules/functor-pair.gandr',NULL,'#280 #1283 #1989 #2023 #2024');
