INSERT INTO feature VALUES('implicit-arguments','checking','Implicit arguments',NULL,'partial','ordinary',NULL,'Arguments the checker supplies through a prefix telescope, contextual metavariables and a spine pass. Rung A landed: implicits declared in one @[...] prefix block, the core telescope interleaved by dependency, supply by name through the slot (f[i = e]), a standing supply. Rung B landed: the solver (#1213) binds a contextual metavariable only where an equation forces a most general solution, postponing every other equation in one store by reason and blockers and refuting only a clash of introduction forms or a strongly rigid occurrence; the spine pass (#1216) makes each implicit a call omits a hole the call nominates, declared at the call''s binders, bound by the comparison that decodes it, and supplied in the body the checker emits, so the kernel never meets a metavariable. An implicit nothing forces is refused ImplicitUnsolved with the solver''s reason, and two arguments disagreeing on one are a type mismatch. Rung C remains.','core-term surface-lowering core-unify core-checker surface-pretty surface-diagnostics','corpus/classifier/implicit-telescope.gandr corpus/pathological/classifier/implicit-telescope.gandr crates/core-unify/tests/solve.rs crates/core-checker/src/bridge/tests.rs::an_omitted_implicit_is_supplied_before_the_kernel_1216','corpus/classifier/implicit-telescope.gandr','#315','#1186 #1213 #1924');
INSERT INTO feature VALUES('imports','modules','Imports',NULL,'implemented','ordinary',NULL,'An import brings another module''s names into scope through the namespace engine.','surface-lowering','corpus/surface/module-import.gandr corpus/pathological/modules/import-unresolved.gandr corpus/pathological/modules/import-shadows.gandr','corpus/ledger/features/imports.gandr',NULL,'aced9bb');
INSERT INTO feature VALUES('incremental-checking','incremental','Incremental checking',NULL,'implemented','notable',NULL,'An edit rejudges only the items whose consulted answers changed, matching a batch check; the language server''s recheck resumes the import closure instead of readmitting it, and lowers the document''s own source alone over the closure''s lowering, held once per process, sharing the closure''s plans rather than copying them; the closure''s origins are carried once per judgement, and each source''s node tables are forgotten once it is lowered, so the suspended lowering holds none of the closure''s; the closure''s scope tables are finished once when it is suspended, and the document''s finish extends them with its own. The closure is judged once and the document on a copy of its context, the program, settle report and spellings joined at the boundary. The incremental pass''s state after the closure''s items is led once per closure and root, and each revision is submitted after it, encoding and judging only its own items; the hover table types the document on the closure''s context.','core-incremental','crates/core-incremental/tests/incremental.rs crates/core-incremental/src/session/tests.rs crates/surface-session/tests/session.rs crates/surface-session/tests/checkpoint.rs crates/surface-lsp/tests/session.rs crates/core-checker/src/bridge/tests.rs crates/surface-lowering/tests/namespace.rs crates/surface-lowering/src/lower/plans.rs crates/surface-dispatcher/src/compose.rs crates/core-checker/tests/recursive_data.rs',NULL,NULL,'#101 #801 #1060 #1137 #1151 #1156 #1159 #1162 #1276 #1279 #1290 #1297 #1302 #1325');
INSERT INTO feature VALUES('incremental-parsing','syntax','Incremental re-parsing','total-parsing','implemented','notable',NULL,'An edit relabels around itself and re-molds only the top-level forms it touched.','surface-parser surface-session','crates/surface-session/tests/edit.rs',NULL,NULL,'#101');
INSERT INTO feature VALUES('indexed-data','types','Indexed data families','nominal-data','partial','notable',NULL,'Data families indexed by values, admitted at their stated indices with the header''s kind and the index binders typed; a case on one checks each arm at its own constructor''s fields and binds past them one equation per index, from the index its constructor states to the scrutinee''s, and at a family of one index an arm whose constructor stands apart from the scrutinee''s index is left out; pruning at several indices and refinement by unification at a match owed.','kernel-core kernel-term core-term core-checker core-nbe core-sequent core-incremental surface-lowering surface-pretty','corpus/model/data/vectors.gandr corpus/pathological/data/vectors.gandr corpus/model/data/vector-cases.gandr corpus/model/data/vector-head.gandr corpus/pathological/data/vector-head.gandr','corpus/model/data/vectors.gandr','#1314','#961 #1963 #1969');
