INSERT INTO feature VALUES('lsp-completion','editor','Completion','language-server','implemented','ordinary',NULL,'The names and keywords the word at the cursor may complete to, chosen by the slot the parser''s continuations name: binders in scope innermost first, declared names from a sorted list per text cut by prefix, keywords in grammar order, a completed keyword inserting its form as a snippet with its tab stops, a completed call its parameters as stops; after them, the names a source under the opened folders declares that no import reaches, each with its import line as detail and the import as an additional edit, from the workspace-symbol index; `isIncomplete: false`.','surface-lsp surface-dispatcher surface-lowering','crates/surface-lsp/src/complete.rs crates/surface-lsp/tests/session.rs crates/surface-lsp/src/server.rs',NULL,'#764','#834 #1412 #1431 #1779');
