INSERT INTO feature VALUES('lsp-pull-diagnostics','editor','Pulled diagnostics','language-server','implemented','ordinary',NULL,'A client that pulls a document''s diagnostics is answered what its copy last published, named by the BLAKE3 digest of their JSON text, and answered unchanged when it names that digest; a pull waits for the copy''s judgement, a change before it is judged cancelling the pull for the client to ask again, nothing is published to it, and a publication no pull waited for asks it to pull again when it refreshes. Diagnostics of sources no editor holds are not answered.','surface-lsp','crates/surface-lsp/src/server.rs',NULL,'#764','#1809');
