INSERT INTO feature VALUES('lsp-watched-files','editor','Watched files','language-server','implemented','ordinary',NULL,'A client with dynamic registration is asked at `initialized` to watch `**/*.gandr`; a change on disk rechecks and republishes only the held copies whose last closure named that path, a missing import''s path included, so writing the file heals its importer; the editor''s own copy of a changed file is never replaced from disk. A closure''s read of a file a watcher reports stands without a look at the disk until the watcher reports it; every other file is confirmed at each lay-out.','surface-lsp surface-dispatcher','crates/surface-lsp/src/server.rs crates/surface-dispatcher/src/component.rs',NULL,'#764','#848 #1523');
INSERT INTO feature VALUES('lsp-workspace-symbol','editor','Workspace symbols','language-server','implemented','ordinary',NULL,'A query finds every name the open documents'' import closures declare, constructors included, and every name a source under the opened folders declares that no editor holds, by subsequence match on the lowercased name, at most 128 sorted by name; a closure''s names come from a per-copy index read off the type table, a source''s from its outline, read from one parse and kept under its file''s length and modification time, built on the first request.','surface-lsp surface-dispatcher','crates/surface-lsp/src/search.rs crates/surface-lsp/src/files.rs',NULL,'#764','#851 #1772');
