INSERT INTO feature VALUES('region-indices','effects','Region indices (a value kept in a scope''s or a hold''s region)','temporary-access','implemented','uncommon','mainstream languages','A value kept in a region, `A at c` for a capability scope or `A at s` for a hold, lives as long as the scope or the hold rather than the access that lent it: a shared view kept there keeps its held value frozen until the region ends, a value kept in a region is bound again at the type that keeps it and never leaves the region, a fork whose protocol carries a value kept in a region is refused since no region bounds a forked peer, and a region is a static index ordered by outlives and erased before anything runs. A definition abstracts over a region, `def f @[r : Region] (k : A at r)`, each call placing `r` at the shortest region its arguments show; it cannot keep what it is lent past `r`, and a region binder named as a value is refused. Such a function commutes with the outlives widening: run at an outer region with its answer widened, it is one function with itself run at an inner region after its argument is widened, a path the conversion checks. A diagnostic spells a type kept at a scope, a hold or a binder by the name the source writes for it.','core-term core-checker core-incremental core-unify surface-lowering surface-pretty surface-diagnostics surface-dispatcher','corpus/model/control/kept-view.gandr corpus/pathological/control/kept-view.gandr corpus/pathological/completion/region-ended.gandr corpus/model/strings/views.gandr corpus/pathological/strings/views.gandr corpus/model/regions/lent.gandr corpus/model/regions/passed.gandr corpus/pathological/regions/stashed.gandr corpus/pathological/regions/named.gandr corpus/pathological/regions/outlived.gandr corpus/model/regions/held-within.gandr corpus/pathological/regions/held-within.gandr corpus/model/regions/natural.gandr corpus/pathological/regions/natural.gandr crates/surface-diagnostics/tests/diagnostics.rs::a_mismatch_between_two_region_binders_names_both_2138','corpus/model/control/kept-view.gandr','#2139','#1244 #1256 #1260 #1454 #1529 #2147');
INSERT INTO feature VALUES('relative-monads','effects','Monads relative to the shift',NULL,'planned','uncommon','mainstream languages','A monad relative to `-F`, a unit and an extension over a family of computation types, declared as a theory with its laws as rules: each model proves them where it is sealed, completion orients them for fusion, and the extension''s continuation is a host thunk. The host half checks today: the option monad''s operations and code polymorphic in the carrier.',NULL,'corpus/model/desc/relative-monad.gandr corpus/pathological/desc/relative-monad.gandr',NULL,'#1951',NULL);
