INSERT INTO feature VALUES('rule-coincidence','rules','Rule coincidence at checks','presented-types','implemented','notable',NULL,'A block''s rules must join every critical pair under a terminating order, or the block is refused naming the diverging pair.','surface-dispatcher theory-coherent-resolutions surface-lowering theory-levitation','corpus/model/desc/rules-overlap-joinable.gandr corpus/pathological/desc/rules-diverge.gandr crates/surface-corpus/src/kernel_export.rs corpus/model/identity/group-laws.gandr corpus/model/desc/rules-completed.gandr corpus/pathological/desc/rules-uncompleted.gandr crates/kernel-core/src/ruled/tests.rs corpus/pathological/desc/second-order-rules.gandr','corpus/model/desc/rules-overlap-joinable.gandr',NULL,'#331 #1040 #1048 #1071 #1139 #1442 #1653 #1661 #1672 #1678 #1706');
INSERT INTO feature VALUES('rule-completion','rules','Rule completion','rule-coincidence','implemented','ordinary',NULL,'A block''s critical pair that parts at a non-value is completed by the rule it derives, oriented by the block''s path order and certified by the pair''s two paths; only a join of two values is refused. A `data` block''s derived rules reach the kernel with the written ones. A derived rule that embeds the rule derived from one of its pair''s cells, wrapping it at one point where no held rule rewrites a further wrapping, is refused `RulesNeverComplete` naming both rounds: every round would derive a longer rule.','surface-lowering theory-levitation theory-coherent-resolutions theory-computads','corpus/model/identity/group-laws.gandr corpus/model/desc/rules-completed.gandr corpus/pathological/desc/rules-uncompleted.gandr corpus/pathological/desc/rules-never-complete.gandr','corpus/model/identity/group-laws.gandr',NULL,'#1048 #1139 #1635 #1653 #1661 #1672 #1678 #1706');
INSERT INTO feature VALUES('rule-equations','rules','Rules as equations (<=>)','presented-types','implemented','notable',NULL,'`rule l <=> r` states an equation and the path order chooses its direction, `==>` pinning one.','surface-lowering','corpus/model/data/rule-equation.gandr corpus/pathological/data/rule-equation-unoriented.gandr','corpus/ledger/features/rule-equations.gandr',NULL,'#382');
INSERT INTO feature VALUES('rule-respect','rules','Case analysis respects rules','presented-types','implemented','notable',NULL,'A case over a presented type must give equal answers on both sides of every rule, the kernel re-deriving the check.','core-checker kernel-core','corpus/model/identity/set-fold.gandr corpus/pathological/data/nested-call-tells-apart.gandr','corpus/model/identity/set-fold.gandr','#357','#359');
INSERT INTO feature VALUES('run-entry','runtime','Program entry',NULL,'implemented','ordinary',NULL,'A source declaring a top-level `main` is a program: `gandr run` runs `main`, given the arguments after the path as a `List(String)` when it takes them, and exits with the integer it returns or passes to `Proc.exit`; a `main` of any other type is refused by name. A run that reaches a hole stops there and names it where the source writes it.','surface-lowering surface-dispatcher surface-driver core-sequent','corpus/model/programs/entry.gandr corpus/model/programs/draft.gandr corpus/model/control/program-exit.gandr corpus/ledger/diagnostics/EntryType.gandr','corpus/model/programs/entry.gandr',NULL,'#2069 #2080');
INSERT INTO feature VALUES('run-prefixes','sessions','Recorded prefixes (Prefix(S))','session-types','implemented','notable',NULL,'A record of the moves a protocol admits so far, open or complete, is a `Prefix(S)`, checked by the monitor that admits runs, a move the protocol refuses refused by name; `Run(S)` holds only complete runs, and no prefix converts to one. An open prefix rides forward along a session flow and stays open, by conversion and on the machine, a move the flow''s target refuses refused at that move.','core-term core-checker core-session surface-lowering','corpus/model/sessions/seat-prefix.gandr corpus/pathological/sessions/seat-prefix.gandr crates/core-checker/src/flow/tests.rs::a_prefix_admits_an_open_run_and_refuses_by_move corpus/model/sessions/seat-prefix-evolution.gandr corpus/pathological/sessions/seat-prefix-evolution.gandr crates/core-checker/src/flow/tests.rs::a_prefix_rides_forward_and_refuses_by_move','corpus/model/sessions/seat-prefix.gandr',NULL,'#1923 #1925');
INSERT INTO feature VALUES('run-targets','runtime','Run targets','running-programs','implemented','ordinary',NULL,'A source''s final expression is its run target: the lowering admits it after every name the source declares, as the body of a thunk, and an expression standing before another root form is a stray, refused where it stands. No signature can be written for it, so the checker types the thunk standing for it by the computation it suspends and enters it at that thunk type, which the kernel checks it against; an unsigned thunk anywhere else still refuses to synthesise. `gandr run` runs a source''s `main`, else its run target, else the last name it declares.','surface-lowering surface-dispatcher core-checker core-incremental','crates/surface-lowering/src/module.rs::the_last_root_expression_is_the_run_target_1105 crates/surface-dispatcher/src/evaluate.rs::a_final_expression_is_the_run_target_1105 crates/core-checker/src/module/tests.rs::a_run_target_has_the_thunk_type_an_unsigned_thunk_lacks_1105 crates/core-checker/src/bridge/tests.rs::a_run_target_crosses_at_the_thunk_type_it_synthesised_1105 crates/core-incremental/src/codec/tests.rs::a_run_target_s_reason_round_trips_and_is_content_1105 corpus/model/basics/definitions.gandr corpus/model/data/one-shape-families.gandr corpus/pathological/modules/module-linker-late-run-target.gandr corpus/pathological/modules/module-linker-multiple-run-targets.gandr','corpus/model/basics/definitions.gandr',NULL,'#2128');
INSERT INTO feature VALUES('running-programs','runtime','Running programs',NULL,'implemented','ordinary',NULL,'`gandr run` checks a source, focuses it into the command IL, runs it natively or on the portable executor and reads the answer back.','surface-dispatcher core-sequent runtime-emitter','corpus/model/modules/functor-pair.gandr','corpus/model/modules/functor-pair.gandr',NULL,'#3');
INSERT INTO feature VALUES('runs-beside-refusal','corpus','A source that runs while refused as total','corpus-expectations','implemented','ordinary',NULL,'An attribute block that states both runs("…") and refuses("…") settles only when both hold: the program runs to the stated value and the checker refuses it by the named refusal, so a loop with no inferable measure is witnessed running and refused as unbounded in one source.','surface-corpus surface-dispatcher','corpus/pathological/control/accessor-escape.gandr',NULL,NULL,'#1153');
