INSERT INTO feature VALUES('second-order-rules','rules','Second-order rules','rule-coincidence','partial','notable',NULL,'A rule over a binding operation applies a bound variable to one argument per variable it binds (`t(u)`, read as its instantiation), is sorted at its binders by check_desc, oriented by HORPO''s metavariable case and refused where two rules overlap, in the producer and the kernel alike; the rules are decided, never fired, and the model derivation does not yet state a binding operation (#1324).','theory-levitation theory-computads surface-lowering kernel-term','corpus/model/desc/second-order-rules.gandr corpus/pathological/desc/second-order-rules.gandr','corpus/model/desc/second-order-rules.gandr','#1324 #1326','#1442');
