INSERT INTO feature VALUES('sequent-machine','machine','The focused command IL and its machine',NULL,'implemented','notable',NULL,'A core program is focused into a command language of producers and consumers and run on the L machine the stencils define, natively or on the portable executor, with tail calls holding no frame.','core-sequent runtime-stencils runtime-emitter','crates/core-sequent/tests/differential.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('session-identity','sessions','Session identity (Path_U and Flow_U at sessions)','session-types','partial','unique','dependent provers','A protocol''s evolution is a certified path or flow between session types, and a recorded run is transported along it. A recorded run carried along a path between its payload types moves each payload its protocol reads at the path and keeps every move, by conversion and on the machine, which runs the transport as a match on the run''s moves; the machine refuses a run of a recursive session by name. Two protocols whose payload types differ are one type once each differing payload pair is paid with a path, bisim(A, B, p), the paths elaborated to the native certificates the kernel checks; a closed univalence pays a pair as itself, its record checked at the native identity the pair owes, and one over a record a parameter binds is refused.','core-session core-checker core-nbe core-sequent kernel-core','corpus/model/sessions/seat-evolution.gandr corpus/model/sessions/run-transport.gandr corpus/model/sessions/payload-paths.gandr corpus/model/sessions/payload-univalence.gandr corpus/pathological/sessions/reserved.gandr corpus/pathological/sessions/session-payloads-unpaid.gandr corpus/pathological/sessions/payload-univalence.gandr crates/core-sequent/tests/run.rs','corpus/model/sessions/seat-evolution.gandr','#1734','#295 #1912');
INSERT INTO feature VALUES('session-readmission','sessions','Sessions replayed by the kernel','session-types','implemented','notable',NULL,'Readmission erases the session discipline and the kernel replays what a session computes: a session type crosses as the kernel''s session code at the state it stands at, the protocol unfolded there when the state is past its root; a send crosses as its payload returned at the type it was checked at, a select and a close as the unit, a fork as its child and then its parent. A receive crosses as its body reading the received value from an assumption of the value''s type, and an offer as a case on an assumed choice among its arms, each assumption an axiom named in the audit of whatever reads it; an endpoint, sent or received, names no value and needs none.','core-checker','crates/core-checker/src/judgement/session/tests.rs crates/core-checker/src/bridge/tests.rs crates/surface-dispatcher/src/compose.rs corpus/model/sessions/seat-exchange.gandr corpus/model/sessions/receive-payload.gandr','corpus/model/sessions/seat-exchange.gandr',NULL,'#1987 #1319');
INSERT INTO feature VALUES('session-relations','sessions','Session equivalence, subtyping and duality','session-types','implemented','notable',NULL,'Contractive session types are compared by coinductive relation search, each relation exported as a checkable candidate.','core-session','crates/core-session/tests/relations.rs corpus/model/sessions/seat-evolution.gandr','corpus/model/sessions/seat-evolution.gandr',NULL,'#279');
INSERT INTO feature VALUES('session-types','sessions','Binary session types',NULL,'implemented','uncommon','mainstream languages','A channel''s protocol is a type of sends, receives, selections, offers and recursion, its endpoints used linearly. A session type stands as an argument through the type(T) quote; a receive binds its payload linearly, and a channel is delegated as a payload. An endpoint moved into a call or a closer keeps its protocol under its new name and is spent at the old one, an action after the move refused by name. A forked task exercises the authority its parent hands it and outlives no region.','core-session core-checker','corpus/model/sessions/seat-exchange.gandr corpus/pathological/sessions/linearity.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr corpus/model/completion/buffer-moved.gandr corpus/model/completion/cancel-orders.gandr corpus/model/moves/moved-to-closer.gandr corpus/model/moves/moved-through.gandr corpus/pathological/moves/ corpus/model/tasks/authority.gandr corpus/pathological/tasks/outlived.gandr','corpus/model/sessions/seat-exchange.gandr',NULL,'#279 #1149 #1242 #1333 #1351');
