INSERT INTO feature VALUES('sibling-imports','modules','Importing a sibling source','imports','implemented','ordinary',NULL,'An import by path brings a sibling source''s declarations into the importer, which is checked against them; since the fold (#436, closed by #623) every corpus subject is one base source its siblings import, every lemma written once, the dispatcher judging the import-connected component once (#592), and a gate refuses a subject that declares a name twice.','surface-lowering surface-dispatcher','corpus/model/identity/circle-base.gandr corpus/model/data/data-base.gandr corpus/model/universe/ corpus/model/control/ corpus/model/circuit/ corpus/pathological/modules/import-unresolved.gandr corpus/pathological/modules/import-cycle-a.gandr corpus/pathological/modules/import-shadows.gandr corpus/model/higher-cells/magma-base.gandr corpus/model/sessions/seat-base.gandr','corpus/model/identity/circle-base.gandr',NULL,'#544 #623');
INSERT INTO feature VALUES('side-view','editor','The terminal side view','engine-hub','implemented','ordinary',NULL,'`gandr view` follows the hub''s render bus beside an editor, showing each document''s highlights and diagnostic cards.','surface-tui surface-render-remote','crates/surface-render-remote/src/lib.rs',NULL,'#126','#172');
INSERT INTO feature VALUES('signature-help','editor','Signature help','language-server','implemented','ordinary',NULL,'Inside a call''s arguments, the head the called name was written with — a declaration''s, a constructor''s or a binder''s function type — on one line, with its documentation, each parameter with the `///` run written before it (also its hover), and the argument the position writes; from a call index per text and a signature index per closure read off parses already made, the callee from the referent index; a refused declaration keeps its uses.','surface-lsp surface-dispatcher surface-lowering','crates/surface-lsp/src/signature.rs crates/surface-lsp/tests/session.rs crates/surface-lowering/tests/scopes.rs',NULL,'#764','#842 #1800');
INSERT INTO feature VALUES('signature-models','descriptions','Models of a signature (Model(S))','signatures-as-values','implemented','notable',NULL,'`Model(S)` derives a module type from a signature, one component per sort, operation and rule, checked against an instance; an interface operation runs at its type arguments; it also signs a functor''s parameter. A theory''s `oper x : A`, a type alone after the colon, is a constant of that type, answered by a value member; a thunk type after the colon is the operation it curries, and a port at a builtin type derives. `Model(T) with sort x = A` fixes a sort of the model type to a type, as a manifest component the members then read. A theory''s `oper x : Model(T)` nests a model of `T`, answered by a submodule ascribed `Model(T)` and sealed with its enclosing model. `Model(T)` in a type is the bundled record the signature states, node for node the written dependent record (`Σ` over a field a later one names, laws as `Path` fields), so a path between two models is their structure identity read field by field; `pack M` at a manifest `Model(T)` lowers to that record, and a pattern at `Model(T)` opens it. `Model(T) with sort x = A` is itself a type, a chain fixing one sort per `with`: the family in `A` takes an equivalence of carriers to a path between the manifest types by `cong`, and `transport` carries a model along it. A theory with an unindexed sort takes one forgetting map, at every carrier, from its models with those sorts manifest to its models, which puts each carrier back as its field; a manifest model stands where a model of its theory is asked, the checker solving the carriers from the model''s type and applying the map there. The printer writing the map and hover naming it are the next rungs.','surface-lowering core-checker core-term surface-dispatcher','corpus/model/higher-cells/cat-shape.gandr corpus/model/modules/model-ascription.gandr corpus/pathological/modules/model-ascription.gandr corpus/model/modules/model-functor.gandr corpus/model/modules/model-constant.gandr corpus/model/modules/model-operation.gandr corpus/model/modules/model-manifest.gandr corpus/pathological/modules/model-manifest.gandr corpus/model/modules/model-nested.gandr corpus/pathological/modules/model-nested.gandr corpus/model/identity/model-identity.gandr corpus/model/desc/lc/model-record.gandr corpus/model/identity/model-counter.gandr corpus/model/modules/model-manifest-type.gandr corpus/pathological/modules/model-manifest-type.gandr corpus/model/identity/model-counter-manifest.gandr corpus/pathological/identity/model-counter-manifest.gandr crates/surface-lowering/tests/modules/models.rs crates/core-checker/src/module/tests.rs','corpus/model/higher-cells/cat-shape.gandr','#2130','#271 #1022 #1097 #1283 #1292 #1304 #1306 #1328 #1358 #1411 #1477 #1989 #2143');
INSERT INTO feature VALUES('signatures-as-values','descriptions','Signatures as values (sign, Sig)',NULL,'implemented','notable',NULL,'A `theory` block presents sorts, operations and rules as a value of the data type `Theory` (renamed from `sign`/`Sig` by #741).','surface-lowering theory-levitation','corpus/model/desc/generic-arity.gandr corpus/model/desc/desc-inspect.gandr corpus/model/desc/generic-arity-behind.gandr','corpus/ledger/features/signatures-as-values.gandr',NULL,'#350 #1095');
INSERT INTO feature VALUES('sized-integers','types','Sized integer arithmetic','native-primitives','planned','ordinary',NULL,'Fixed-width integer types with their arithmetic primitives on the machine.',NULL,NULL,NULL,'#318',NULL);
INSERT INTO feature VALUES('sized-types','recursion','Sized types',NULL,'partial','notable',NULL,'A staged type is a classifier a type parameter instantiates at, read off the first later variable argument that holds it, erased to its plain code on the wire and re-derived by the kernel at readmission; a size and a map through map at the children''s stage check and readmit on the direct rose tree, the forged claim refuses StageNotBelow; the staged fixpoint stuck past its first position carries its leading arguments, gating at its staged argument in both engines; the size and the map over the direct rose tree run, passing `map` the children''s type as a code. PR 2 owes a stage on a signature (the explicit bounded annotation), the successor and infinity, the consistency gate, measures, and what the erasure cannot re-derive: a nested staged code, a non-variable argument, a callee result stage, a helper parameter at the plain domain. An explicit stage binder is an implicit in the prefix block (def f @[i : Size] (x : Nat[<i])), bounded @[i : Size, i < n], written at the call f[i = s] or solved from every argument that shows it at the least stage the readings allow (from below, from above under a function argument''s domain, exactly inside a data type''s argument), two readings no stage satisfies refused StagesDisagree by name in both engines; a bounded binder read off an argument is checked against its bound at the call in both engines, refused StageNotBelow. A stage supplied by name at a call, f[i = j], is held by the checker to the stage the arguments solve, a disagreement refused StagesDisagree at the call''s head; the supply rides the declaration and its content key, and the kernel re-derives every stage without it.','core-checker kernel-core','corpus/model/data/rose.gandr corpus/model/data/sized-higher-order.gandr corpus/pathological/data/rose.gandr corpus/pathological/data/sized-higher-order.gandr corpus/model/identity/int-accumulated.gandr corpus/model/data/following.gandr corpus/pathological/data/following.gandr','corpus/model/data/rose.gandr','#392','#648 #999 #1022 #1130 #1172 #1253 #1262 #1273');
