INSERT INTO feature VALUES('string-model','effects','A string written in the language','temporary-access','partial','uncommon','mainstream languages','A string written as a corpus subject in the language itself: its bytes inline up to a capacity or in a buffer with a holder count, UTF-8 encoding of code points, a trailing zero for a C reading refused at an interior zero, copy-on-write that copies a buffer only when another string holds it, the in-place write a one-holder string licenses, and views lent by an access or kept in the region of a scope around it. The builtin `String` is not yet replaced by it.','surface-corpus surface-dispatcher','corpus/model/strings/string-base.gandr corpus/model/strings/copy-on-write.gandr corpus/model/strings/views.gandr corpus/pathological/strings/views.gandr','corpus/model/strings/string-base.gandr','#628 #1219','#1260');
INSERT INTO feature VALUES('structural-recursion','recursion','Structural recursion with marked calls',NULL,'implemented','notable',NULL,'def rec f lowers to the core fixpoint staging the parameter its matches take apart, and a call written f[<] carries descent evidence the kernel replays.','core-checker kernel-core core-nbe','corpus/model/data/recursive-addition.gandr','corpus/ledger/features/structural-recursion.gandr',NULL,'#95 #1615');
INSERT INTO feature VALUES('sugared-spelling','printing','Sugared and explicit spellings','presentation-printer','implemented','ordinary',NULL,'Every printing face chooses the most-sugared form or the explicit one, sugared by default; the formatter is at token parity with the printer over whole declarations, bodies included, the declarations held out named by issue.','surface-pretty surface-lsp surface-format','crates/surface-pretty/src/former.rs crates/surface-dispatcher/tests/parity.rs',NULL,NULL,'#347 #828 #1929 #1971');
INSERT INTO feature VALUES('syntax-ledger','workflow','The syntax ledger',NULL,'implemented','notable',NULL,'The language surface enumerated from the grammar itself — every rule and attribute, pinned by the grammar fingerprint, regenerated and compared by a gate; one verified exemplar per rule, the bijection and the mold check gated, every exemplar stating what the checker makes of its form, and every committed rule''s admission read off its exemplar''s lowering.','surface-grammar surface-dispatcher','ledger/syntax.md corpus/ledger/syntax',NULL,NULL,'#763 #770 #1749 #1761 #1762');
INSERT INTO feature VALUES('tarski-universes','universes','User-written Tarski universes',NULL,'implemented','notable',NULL,'A datatype of codes with a recursive decoder checks, an open decode read as a type compared by its code; a constructor argument may be a universe or a function (W-shaped), the eliminator reaching the hypothesis through the function.','core-checker core-nbe','corpus/model/universe/closed.gandr corpus/model/universe/v-infinity.gandr corpus/model/data/w-tree.gandr corpus/pathological/universe/v-infinity.gandr corpus/model/universe/vacuous-pi.gandr corpus/pathological/universe/vacuous-pi.gandr corpus/model/universe/inductive-recursive.gandr','corpus/model/universe/closed.gandr','','#428 #580');
INSERT INTO feature VALUES('temporal-judgement','sessions','The temporal judgement (logical time as a web)','session-types','partial','uncommon','dependent provers','A session''s logical time is a two-colour causal web — each endpoint''s own order and every send before its receipt green, every other pair white — and a recorded dialogue is admitted exactly when its order linearizes the web; a receipt recorded before its send is refused by name. A source writes a binary session''s dialogue as `dialogue(left(…), right(…), …) : Dialogue(S)`, its left endpoint following `S` and its right the dual; two logs that commute independent moves are one dialogue, related by `refl`, and a receipt of another payload or label is refused as unmatched.','core-session theory-deep-inference core-term core-checker core-nbe surface-lowering','crates/core-session/tests/dialogue.rs crates/theory-deep-inference/src/causal_web.rs corpus/model/sessions/dialogue-web.gandr corpus/pathological/sessions/dialogue-web.gandr crates/core-checker/src/flow/tests.rs::a_dialogue_checks_by_its_web_and_refuses_by_move','corpus/model/sessions/dialogue-web.gandr','#316','#1072 #2092');
INSERT INTO feature VALUES('temporary-access','effects','Temporary access (hold and access)',NULL,'implemented','uncommon','mainstream languages','A held value is lent to a view, shared or exclusive; an exclusive view must be ended exactly once, by a write-back `resume` or an `abort` that runs the unwind.','core-term core-checker','corpus/model/control/accessor-counter.gandr corpus/pathological/control/accessor-twice.gandr corpus/model/control/accessor-loop.gandr corpus/model/control/accessor-shared.gandr','corpus/model/control/accessor-counter.gandr',NULL,'#415 #1148 #1180');
