INSERT INTO feature VALUES('termination-certificates','rules','Replayable termination certificates',NULL,'planned','notable',NULL,'One termination evidence form shared by rule blocks and fixpoints: the path order''s precedence as data, a size measure for a fixpoint.',NULL,NULL,NULL,'#314 #392',NULL);
