INSERT INTO feature VALUES('text-primitives','types','Text, pattern and path primitives','native-primitives','partial','ordinary',NULL,'Text primitives on the machine: `string.append` writes the first string then the second, checked at its prelude signature and run on both executors, and an interpolated string `"…${ e }…"` lowers to its appends in written order and prints back as itself; string escaping and scanning, regular-expression extraction and path primitives are still to come.','core-term runtime-emitter surface-lowering surface-pretty','corpus/model/builtins/simple-builtins.gandr corpus/surface/string-interpolation.gandr crates/runtime-emitter/tests/forms.rs','corpus/model/builtins/simple-builtins.gandr','#318 #1505','#1981');
INSERT INTO feature VALUES('theory-include','descriptions','Theory inclusion','signature-models','partial','notable',NULL,'A theory includes another as a function on Theory values with the morphism kept, its parts included or restricted by name; the union''s critical pairs are refused by name. An include names a theory its own source reads before it, or else the one a source it imports unqualified presents, two such sources refused by name; a block that gives two theories it reaches a second join among the theories it sees is refused, the pair and both joins named. A model type fixes a sort by `with sort x = A` (gandr #1306). A theory `T` takes a reduct `T.S` for each theory `S` it includes, directly or through another, the ways round a diamond one reduct: it restricts a model of `T` to the model of `S` the same module gives, by computation, and a model of `T` stands where a model of `S` is asked, the checker applying the reduct there. The explicit form writes the applied reduct as its call, `T.S(m)`; the sugared form leaves a written call to the checker where it would apply the reduct; the printer writing it and hover naming it are the next rungs.','theory-levitation surface-lowering surface-grammar core-checker core-term surface-format surface-dispatcher','corpus/model/include/monoid.gandr corpus/model/include/imported.gandr corpus/model/include/reduct.gandr corpus/model/include/reduct-explicit.gandr corpus/pathological/include/rules-join.gandr corpus/pathological/include/imported-rules.gandr corpus/pathological/include/two-joins.gandr crates/surface-lowering/tests/namespace.rs crates/surface-lowering/tests/modules/models.rs crates/core-checker/src/module/tests.rs crates/surface-dispatcher/src/format.rs','corpus/model/include/monoid.gandr','#1092','#1094 #1237 #1247 #2041 #2059');
INSERT INTO feature VALUES('thunks-and-force','calculus','Thunks and forcing','call-by-push-value','implemented','notable',NULL,'A computation is suspended as a value by `thunk` and resumed by `force`, the type `+U` naming the suspension.','core-term core-nbe','corpus/model/identity/cong-thunk.gandr','corpus/model/identity/cong-thunk.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('top-level-type-members','modules','Type members at a source''s top level','modules','implemented','ordinary',NULL,'`type T = τ ;` at a source''s top level names `τ` for the declarations after it, and for every declaration of a source importing it unqualified, a synonym with parameters too, as a module''s type member does; a use before it is unresolved, a second member of the name refused, and a name two imports write refused at its use.','surface-lowering','corpus/model/modules/top-level-type.gandr corpus/model/modules/top-level-type-imported.gandr corpus/pathological/modules/top-level-type.gandr','corpus/model/modules/top-level-type.gandr',NULL,NULL);
INSERT INTO feature VALUES('total-parsing','syntax','Total, error-tolerant parsing',NULL,'implemented','notable',NULL,'Every source parses to a molded tree, an unfinished form left open with the completion obligations that would close it.','surface-parser','crates/surface-parser/tests/acceptance.rs',NULL,NULL,'b1b373b');
INSERT INTO feature VALUES('trailing-delimiters','syntax','Trailing commas and leading arm bars',NULL,'implemented','ordinary',NULL,'A list may end in a comma and a match''s first arm may begin with a bar.','surface-grammar','strict/trailing-delimiters.gandr','crates/surface-corpus/strict/trailing-delimiters.gandr',NULL,'#141');
INSERT INTO feature VALUES('transport','identity','Transport','identity-types','implemented','notable',NULL,'`transport(P, p, v)` moves an element along an identification through a family; a record moves field by field under its labels, and a suspension whose run performs no effect runs, forced, and its result moves on. A value declared as a transport is computed the first time a run reads it, and every later read is that answer; a transport written as a call''s argument runs before the call.','core-checker core-nbe core-term kernel-core core-sequent runtime-emitter','corpus/model/identity/transport-path.gandr corpus/model/identity/transport-list.gandr corpus/model/identity/flow-large.gandr corpus/model/modules/model-manifest-type.gandr','corpus/ledger/features/transport.gandr',NULL,'#204 #1099 #1852 #1953 #1954 #2145');
INSERT INTO feature VALUES('two-region-store','machine','The two-region store','sequent-machine','implemented','notable',NULL,'Immutable values live in a heap region and continuations in a walkable frame region, each bounded per thread; a run''s answer moves into an immutable answer heap.','runtime-emitter core-sequent','crates/runtime-stencils/tests/exits.rs crates/runtime-emitter/src/run.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('type-codes','universes','Type codes and decoding',NULL,'implemented','uncommon','mainstream languages','A type is quoted as a code in a universe and decoded back, a function into a universe read as a type where one is expected. A type with no expression reading is written type(T) in expression position, the written quote beside the positional one. A quoted session type''s payloads read no variable bound around the quote, as the kernel forms them; a run''s protocol, which stays on the checker''s side, may.','core-term core-checker kernel-core','corpus/model/desc/generic-arity.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr','corpus/model/desc/generic-arity.gandr',NULL,'b87a65d #1149 #1748');
INSERT INTO feature VALUES('typed-holes','checking','Typed holes and goals',NULL,'implemented','notable',NULL,'A hole stands for missing source, is typed where it stands, and is filled by name with the rest of the program still checking.','core-term core-checker','corpus/fragment/addressable-obligation.gandr','corpus/fragment/addressable-obligation.gandr',NULL,'#91');
INSERT INTO feature VALUES('unification','checking','Unification and index refinement',NULL,'planned','notable',NULL,'Unification at a scrutinee''s type refines the context by a match, a clash a refutation and a conversion failure a refusal.',NULL,NULL,NULL,'#391',NULL);
INSERT INTO feature VALUES('uniqueness-of-identity-proofs','identity','Uniqueness of identity proofs',NULL,'declined','notable',NULL,'Identity is untruncated by design, so no type is forced to be a set.',NULL,NULL,NULL,'#1686',NULL);
INSERT INTO feature VALUES('univalence-axiom','identity','Univalence on a record''s laws (ua)',NULL,'partial','uncommon','dependent provers','`ua(e)` makes a bi-invertible record `e : A ≃ B` a path `Path(Type, A, B)` at any two codes, admitted on its laws as typed evidence; transport along it applies the record''s map by conversion; `ua ∘ idtoequiv` and `idtoequiv ∘ ua` are owed until #520 proves them. Transport along ua(e) runs in the machine (#708): the path lowered to its two-map record, the motive by shape (identity, constant, product, sum, list); transport back along `ua(e)` applies the record''s left inverse, and along `p then ua(e)` moves along `p`, then the forward map, and a function moves along `ua(e)` by the record''s maps, its argument back by the left inverse and its result forward, in both checkers, and the machine runs each: the motive by shape (identity, constant, product, sum, list, a pure function, a path between types moving at an endpoint), a transport along `back` or `then` running the transport that computes it first.','kernel-term kernel-core core-term core-nbe core-checker core-sequent surface-lowering','corpus/model/identity/univalence.gandr corpus/pathological/identity/univalence.gandr corpus/model/identity/univalence-back.gandr corpus/model/identity/univalence-then.gandr corpus/model/identity/univalence-function.gandr corpus/model/identity/transport-path.gandr corpus/model/identity/univalence-transports.gandr corpus/model/identity/certificate-transport.gandr','corpus/model/identity/univalence.gandr','#312','#692 #958 #984 #990 #1103');
INSERT INTO feature VALUES('univalence-per-stratum','identity','Univalence by certified conversion (ua[n, k])',NULL,'implemented','unique','dependent provers','`ua[n, k]` turns an equivalence of presentations into a path in the universe at every stratum the site certifies, replayed by the kernel and never postulated.','core-checker kernel-core theory-sites','corpus/model/higher-cells/ua-corolla.gandr corpus/model/higher-cells/ua-corolla-strata.gandr corpus/model/higher-cells/ua-by-hand.gandr','corpus/model/higher-cells/ua-corolla.gandr',NULL,'#263');
